  1	package com.pousadamarealta;
  2	
  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousadamarealta.api.controller.*;
  7	import com.pousadamarealta.api.dto.ErrorResponse;
  8	import com.pousadamarealta.database.*;
  9	import com.pousadamarealta.exception.*;
 10	import com.pousadamarealta.messaging.MessageService;
 11	import com.pousadamarealta.service.*;
 12	import io.javalin.Javalin;
 13	import io.javalin.http.HttpStatus;
 14	
 15	public class Application {
 16	    public static void main(String[] args) {
 17	        String dbUrl = System.getenv("DB_URL");
 18	        String dbUser = System.getenv("DB_USER");
 19	        String dbPassword = System.getenv("DB_PASSWORD");
 20	        String portStr = System.getenv("PORT");
 21	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 22	
 23	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 24	            throw new IllegalStateException("Database configuration required: DB_URL, DB_USER, DB_PASSWORD");
 25	        }
 26	
 27	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 28	
 29	        DatabaseManager dbManager = new DatabaseManager(dbUrl, dbUser, dbPassword);
 30	
 31	        RoomDAO roomDAO = new RoomDAO(dbManager);
 32	        ReservationDAO reservationDAO = new ReservationDAO(dbManager);
 33	        MessageDAO messageDAO = new MessageDAO(dbManager);
 34	
 35	        RoomService roomService = new RoomService(roomDAO);
 36	        PricingService pricingService = new PricingService();
 37	        MessageService messageService = new MessageService(messageDAO, testMode);
 38	        ReservationService reservationService = new ReservationService(
 39	            reservationDAO, roomService, pricingService, messageService);
 40	        ReportService reportService = new ReportService(roomService, reservationDAO);
 41	
 42	        RoomController roomController = new RoomController(roomService);
 43	        ReservationController reservationController = new ReservationController(reservationService);
 44	        MessageController messageController = new MessageController(messageService);
 45	        ReportController reportController = new ReportController(reportService);
 46	
 47	        ObjectMapper objectMapper = new ObjectMapper();
 48	        objectMapper.registerModule(new JavaTimeModule());
 49	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 50	
 51	        Javalin app = Javalin.create(config -> {
 52	            config.jsonMapper(new io.javalin.json.JsonMapper() {
 53	                @Override
 54	                public String toJsonString(Object obj, java.lang.reflect.Type type) {
 55	                    try {
 56	                        return objectMapper.writeValueAsString(obj);
 57	                    } catch (Exception e) {
 58	                        throw new RuntimeException(e);
 59	                    }
 60	                }
 61	
 62	                @Override
 63	                public <T> T fromJsonString(String json, java.lang.reflect.Type targetType) {
 64	                    try {
 65	                        return objectMapper.readValue(json, objectMapper.constructType(targetType));
 66	                    } catch (Exception e) {
 67	                        throw new RuntimeException(e);
 68	                    }
 69	                }
 70	            });
 71	        });
 72	
 73	        app.get("/rooms", roomController::getAllRooms);
 74	
 75	        app.post("/reservations", reservationController::createReservation);
 76	        app.get("/reservations/{id}", reservationController::getReservation);
 77	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 78	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 79	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 80	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 81	        app.get("/reservations/{id}/document", reservationController::getDocument);
 82	
 83	        app.get("/messages", messageController::getAllMessages);
 84	
 85	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 86	        app.get("/reports/revenue", reportController::getRevenueReport);
 87	
 88	        app.exception(InvalidRequestException.class, (e, ctx) -> {
 89	            ctx.status(HttpStatus.BAD_REQUEST)
 90	                .json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
 91	        });
 92	
 93	        app.exception(RoomNotFoundException.class, (e, ctx) -> {
 94	            ctx.status(HttpStatus.NOT_FOUND)
 95	                .json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
 96	        });
 97	
 98	        app.exception(ReservationNotFoundException.class, (e, ctx) -> {
 99	            ctx.status(HttpStatus.NOT_FOUND)
100	                .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
101	        });
102	
103	        app.exception(RoomUnavailableException.class, (e, ctx) -> {
104	            ctx.status(HttpStatus.CONFLICT)
105	                .json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
106	        });
107	
108	        app.exception(OperationNotAllowedException.class, (e, ctx) -> {
109	            ctx.status(HttpStatus.CONFLICT)
110	                .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
111	        });
112	
113	        app.exception(CapacityExceededException.class, (e, ctx) -> {
114	            ctx.status(HttpStatus.UNPROCESSABLE_CONTENT)
115	                .json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
116	        });
117	
118	        app.exception(NumberFormatException.class, (e, ctx) -> {
119	            ctx.status(HttpStatus.BAD_REQUEST)
120	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid number format"));
121	        });
122	
123	        app.exception(com.fasterxml.jackson.core.JsonProcessingException.class, (e, ctx) -> {
124	            ctx.status(HttpStatus.BAD_REQUEST)
125	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid JSON"));
126	        });
127	
128	        app.start(port);
129	
130	        System.out.println("Server started on port " + port);
131	    }
132	}
