141	public class ArchiveCopyRule implements MessageRule {
142	    private static final String ARCHIVE_EMAIL = "arquivo@pousadamarealta.com.br";
143	
144	    @Override
145	    public List<Message> apply(Message message) {
146	        List<Message> messages = new ArrayList<>();
147	        messages.add(message);
148	
149	        if (message.getStatus() == MessageStatus.SENT) {
150	            Message copy = new Message(
151	                message.getChannel(),
152	                ARCHIVE_EMAIL,
153	                "[Cópia] " + message.getSubject(),
154	                message.getBody(),
155	                MessageStatus.SENT
156	            );
157	            messages.add(copy);
158	        }
159	
160	        return messages;
161	    }
162	}
163	package com.pousadamarealta.messaging;
164	
165	import com.pousadamarealta.domain.Message;
166	import com.pousadamarealta.domain.MessageStatus;
167	
168	import java.util.Collections;
169	import java.util.List;
170	
171	public class EmailValidationRule implements MessageRule {
172	    @Override
173	    public List<Message> apply(Message message) {
174	        if (!isValidEmail(message.getTo())) {
175	            message.setStatus(MessageStatus.BLOCKED);
176	        } else {
177	            message.setStatus(MessageStatus.SENT);
178	        }
179	        return Collections.singletonList(message);
180	    }
181	
182	    private boolean isValidEmail(String email) {
183	        if (email == null || email.isEmpty()) {
184	            return false;
185	        }
186	
187	        int atIndex = email.indexOf('@');
188	        if (atIndex <= 0 || atIndex != email.lastIndexOf('@')) {
189	            return false;
190	        }
191	
192	        String beforeAt = email.substring(0, atIndex);
193	        String afterAt = email.substring(atIndex + 1);
194	
195	        if (beforeAt.isEmpty() || afterAt.isEmpty()) {
196	            return false;
197	        }
198	
199	        return afterAt.contains(".");
200	    }
201	}
