218	
219	public class MessageService {
220	    private final MessageDAO messageDAO;
221	    private final List<MessageRule> rules;
222	
223	    public MessageService(MessageDAO messageDAO, boolean testMode) {
224	        this.messageDAO = messageDAO;
225	        this.rules = new ArrayList<>();
226	
227	        rules.add(new EmailValidationRule());
228	
229	        if (testMode) {
230	            rules.add(new TestModeRule());
231	        } else {
232	            rules.add(new ArchiveCopyRule());
233	        }
234	    }
235	
236	    public void sendMessage(MessageChannel channel, String to, String subject, String body) {
237	        Message message = new Message(channel, to, subject, body, null);
238	
239	        List<Message> messagesToSave = new ArrayList<>();
240	        messagesToSave.add(message);
241	
242	        for (MessageRule rule : rules) {
243	            List<Message> currentMessages = new ArrayList<>();
244	            for (Message msg : messagesToSave) {
245	                currentMessages.addAll(rule.apply(msg));
246	            }
247	            messagesToSave = currentMessages;
248	        }
249	
250	        for (Message msg : messagesToSave) {
251	            messageDAO.save(msg);
252	        }
253	    }
254	
255	    public List<Message> getAllMessages() {
256	        return messageDAO.findAll();
257	    }
258	}
