367	    private String formatCpf(String cpf) {
368	        if (cpf.length() == 11) {
369	            return String.format("%s.%s.%s-%s",
370	                cpf.substring(0, 3),
371	                cpf.substring(3, 6),
372	                cpf.substring(6, 9),
373	                cpf.substring(9, 11));
374	        }
375	        return cpf;
376	    }
