 10	public class PricingService {
 11	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 12	
 13	    public BigDecimal calculateNightlyRate(RoomType roomType, LocalDate date) {
 14	        BigDecimal baseRate = roomType.getNightlyRate();
 15	
 16	        if (isHighSeason(date)) {
 17	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER)
 18	                .setScale(2, RoundingMode.HALF_EVEN);
 19	        }
 20	
 21	        return baseRate;
 22	    }
 23	
 24	    public BigDecimal calculateSubtotal(RoomType roomType, LocalDate checkIn, LocalDate checkOut) {
 25	        BigDecimal total = BigDecimal.ZERO;
 26	        LocalDate currentDate = checkIn;
 27	
 28	        while (currentDate.isBefore(checkOut)) {
 29	            BigDecimal nightlyRate = calculateNightlyRate(roomType, currentDate);
 30	            total = total.add(nightlyRate);
 31	            currentDate = currentDate.plusDays(1);
 32	        }
 33	
 34	        return total.setScale(2, RoundingMode.HALF_EVEN);
 35	    }
 36	
 37	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
 38	        BigDecimal discountAmount = subtotal.multiply(ratePlan.getDiscountRate());
 39	        return discountAmount.setScale(2, RoundingMode.HALF_EVEN);
 40	    }
 41	
 42	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
 43	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
 44	    }
