323	        document.put("title", "Comprovante de reserva");
324	        document.put("reservationId", reservation.getId());
325	        document.put("guestName", reservation.getGuestName());
326	        document.put("guestCpf", reservation.getGuestCpf());
327	        document.put("roomNumber", reservation.getRoomNumber());
328	        document.put("roomType", room.getType().name());
329	        document.put("checkIn", reservation.getCheckIn().toString());
330	        document.put("checkOut", reservation.getCheckOut().toString());
331	        document.put("nights", reservation.getNights());
332	        document.put("subtotal", reservation.getSubtotal());
333	        document.put("discount", reservation.getDiscount());
334	        document.put("total", reservation.getTotal());
335	        return document;
336	    }
337	
338	    private String formatReceipt(Reservation reservation, Room room) {
339	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
340	
341	        StringBuilder receipt = new StringBuilder();
342	        receipt.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
343	        receipt.append(String.format("Hóspede: %s (CPF %s)\n",
344	            reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
345	        receipt.append(String.format("Quarto: %s (%s)\n",
346	            reservation.getRoomNumber(), room.getType().name()));
347	        receipt.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
348	            reservation.getCheckIn().format(dateFormatter),
349	            reservation.getCheckOut().format(dateFormatter),
350	            reservation.getNights(),
351	            reservation.getNights() == 1 ? "diária" : "diárias"));
352	        receipt.append(String.format("Diárias: %s\n", formatMoney(reservation.getSubtotal())));
353	
354	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
355	            receipt.append(String.format("Desconto: %s\n", formatMoney(reservation.getDiscount())));
356	        }
357	
358	        receipt.append(String.format("Total: %s", formatMoney(reservation.getTotal())));
359	
360	        return receipt.toString();
361	    }
362	
363	    private String formatMoney(BigDecimal amount) {
364	        return String.format("R$ %,.2f", amount).replace(",", "X").replace(".", ",").replace("X", ".");
365	    }
366	
367	    private String formatCpf(String cpf) {
368	        if (cpf.length() == 11) {
369	            return String.format("%s.%s.%s-%s",
370	                cpf.substring(0, 3),
371	                cpf.substring(3, 6),
372	                cpf.substring(6, 9),
373	                cpf.substring(9, 11));
374	        }
375	        return cpf;
376	    }
377	}
