 25	    private void initializeDatabase() {
 26	        String createRoomsTable = """
 27	            CREATE TABLE IF NOT EXISTS rooms (
 28	                number VARCHAR(10) PRIMARY KEY,
 29	                type VARCHAR(20) NOT NULL,
 30	                capacity INT NOT NULL,
 31	                nightly_rate DECIMAL(10, 2) NOT NULL
 32	            )
 33	            """;
 34	
 35	        String createReservationsTable = """
 36	            CREATE TABLE IF NOT EXISTS reservations (
 37	                id SERIAL PRIMARY KEY,
 38	                room_number VARCHAR(10) NOT NULL,
 39	                guest_name VARCHAR(255) NOT NULL,
 40	                guest_email VARCHAR(255) NOT NULL,
 41	                guest_cpf VARCHAR(14) NOT NULL,
