 46	                nights INT NOT NULL,
 47	                subtotal DECIMAL(10, 2) NOT NULL,
 48	                discount DECIMAL(10, 2) NOT NULL,
 49	                total DECIMAL(10, 2) NOT NULL,
 50	                status VARCHAR(20) NOT NULL,
 51	                amount_paid DECIMAL(10, 2) NOT NULL,
 52	                refund DECIMAL(10, 2),
 53	                FOREIGN KEY (room_number) REFERENCES rooms(number)
 54	            )
 55	            """;
 56	
 57	        String createMessagesTable = """
 58	            CREATE TABLE IF NOT EXISTS messages (
 59	                id SERIAL PRIMARY KEY,
 60	                channel VARCHAR(20) NOT NULL,
 61	                recipient VARCHAR(255) NOT NULL,
 62	                subject VARCHAR(500) NOT NULL,
 63	                body TEXT NOT NULL,
 64	                status VARCHAR(20) NOT NULL
 65	            )
 66	            """;
