 68	        try (Connection conn = getConnection();
 69	             Statement stmt = conn.createStatement()) {
 70	            stmt.execute(createRoomsTable);
 71	            stmt.execute(createReservationsTable);
 72	            stmt.execute(createMessagesTable);
 73	            initializeRooms();
 74	        } catch (SQLException e) {
 75	            throw new RuntimeException("Failed to initialize database", e);
 76	        }
